package com.amplayer.portable;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.provider.MediaStore;import android.view.*;import android.webkit.*;import org.json.*;import java.io.*;import java.nio.*;import java.util.*;
public class Queue214Instrumentation extends Instrumentation {
 private JSONObject settings;private final List<Uri> created=new ArrayList<>();
 private void report(String key,String value){Bundle b=new Bundle();b.putString(key,value);sendStatus(0,b);}
 private WebView web(View v){if(v instanceof WebView)return (WebView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){WebView found=web(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
 private JSONObject track(String name)throws Exception{ContentValues values=new ContentValues();values.put(MediaStore.Audio.Media.DISPLAY_NAME,"AMPlayer-queue-"+name+"-"+System.currentTimeMillis()+".wav");values.put(MediaStore.Audio.Media.MIME_TYPE,"audio/wav");values.put(MediaStore.Audio.Media.RELATIVE_PATH,"Music/AMPlayerTest");Uri uri=getTargetContext().getContentResolver().insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new Exception("Fixture failed");created.add(uri);int bytes=16000*40;ByteBuffer wave=ByteBuffer.allocate(44+bytes).order(ByteOrder.LITTLE_ENDIAN);wave.put("RIFF".getBytes()).putInt(36+bytes).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(8000).putInt(16000).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(bytes);try(OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){out.write(wave.array());}return new JSONObject().put("name",name).put("type","local").put("path",uri.toString());}
 private void save()throws Exception{Store.save(getTargetContext(),settings.toString());}
 private JSONObject status()throws Exception{return new JSONObject(PlaybackService.status());}
 private String path(JSONObject s){return s.optJSONObject("item")==null?"":s.optJSONObject("item").optString("path");}
 private JSONObject await(String expected)throws Exception{JSONObject s=new JSONObject();for(int n=0;n<100;n++){Thread.sleep(200);s=status();if(path(s).equals(expected)&&s.optBoolean("playing"))return s;}throw new Exception("Expected "+expected+" but got "+s);}
 private void startTrack(JSONObject item,String context)throws Exception{JSONObject value=new JSONObject(item.toString()).put("playbackContext",context);settings.put("playbackContext",context);save();runOnMainSync(()->getTargetContext().startForegroundService(new Intent(getTargetContext(),PlaybackService.class).setAction("item").putExtra("item",value.toString())));await(item.getString("path"));}
 private void command(String name){runOnMainSync(()->getTargetContext().startService(new Intent(getTargetContext(),PlaybackService.class).setAction(name)));}
 private void endTrack(){runOnMainSync(()->PlaybackService.seek(39700));}
 private void repeats(String expected)throws Exception{endTrack();boolean wrapped=false;for(int n=0;n<100;n++){Thread.sleep(150);JSONObject s=status();if(!path(s).equals(expected))throw new Exception("Single repeat changed track: "+s);if(s.optBoolean("playing")&&s.optLong("position")<15000){wrapped=true;break;}}if(!wrapped)throw new Exception("Single repeat did not restart");}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();JSONObject original=Store.load(getTargetContext());try{
  Activity activity=startActivitySync(new Intent().setClassName(getTargetContext(),"com.amplayer.portable.QueueHostActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1800);runOnMainSync(()->{WebView w=web(activity.getWindow().getDecorView());if(w!=null)w.getSettings().setJavaScriptEnabled(false);});Thread.sleep(400);
  JSONObject a=track("A favorite"),b=track("B local only"),c=track("C favorite");String ap=a.getString("path"),bp=b.getString("path"),cp=c.getString("path");settings=new JSONObject(original.toString()).put("volume",0).put("autoUpdate",false).put("localFiles",new JSONArray().put(a).put(b).put(c)).put("favorites",new JSONArray().put(a).put(new JSONObject().put("name","Radio").put("type","radio").put("url","https://example.test/live")).put(c)).put("favoriteMusicMode","list").put("localPlayMode","one");
  startTrack(a,"favoriteMusic");endTrack();await(cp);endTrack();await(ap);report("favoriteLoop","PASS A -> C -> A; nonfavorite B and radio excluded, independent from local repeat-one preference");
  settings.put("favoriteMusicMode","one");save();repeats(ap);command("next");await(cp);command("previous");await(ap);report("favoriteOne","PASS repeat one, with manual next/previous restricted to favorite queue");
  settings.put("localPlayMode","list");startTrack(a,"local");command("next");await(bp);report("localScope","PASS local queue includes nonfavorite B");
  settings.put("localPlayMode","one");save();repeats(bp);report("localOne","PASS local repeat one");
  settings.put("localPlayMode","shuffle");save();String previous=bp;Set<String> allowed=new HashSet<>(Arrays.asList(ap,bp,cp));for(int n=0;n<4;n++){String before=path(status());command("next");JSONObject next=new JSONObject();boolean changed=false;for(int wait=0;wait<100;wait++){Thread.sleep(150);next=status();if(next.optBoolean("playing")&&!path(next).equals(before)){changed=true;break;}}if(!changed||!allowed.contains(path(next)))throw new Exception("Shuffle invalid: "+next);previous=before;}command("previous");await(previous);report("shuffle","PASS four random transitions without immediate repeat; previous returns actual history");
  settings.put("favoriteMusicMode","list");startTrack(a,"favoriteMusic");settings.put("favorites",new JSONArray());save();endTrack();boolean stopped=false;for(int n=0;n<60;n++){Thread.sleep(150);if(!status().has("item")){stopped=true;break;}}if(!stopped)throw new Exception("Empty favorite queue did not stop");report("emptyQueue","PASS removed favorite queue stops instead of playing local-only files");result.putString("result","PASS");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}finally{getTargetContext().stopService(new Intent(getTargetContext(),PlaybackService.class));for(Uri uri:created)getTargetContext().getContentResolver().delete(uri,null,null);try{Store.save(getTargetContext(),original.toString());}catch(Exception ignored){}}}
}
